def cpu_saturata_carico_query(m):
    cpu = m.get("cpu_pct")
    thr = m.get("threads_running")
    cores = m.get("cpu_cores")
    if cpu is None or thr is None or cores is None:
        return None
    if cores <= 0:
        return None
    if cpu >= 95 and thr >= cores * 2:
        return diagnosis("cpu_saturata_carico_query", "critico", "cpu", {"cpu_pct": cpu, "threads_running": thr, "cpu_cores": cores, "threads_per_core": round(thr / cores, 2)}, "Individuare le query che generano il carico, ottimizzarle o limitarle, e ridistribuire il traffico verso gli altri worker o aumentare le CPU.")
    return None

